// Section XIV.A - Asset Chaining Rule
// Define primary content assets and their derivative chains
// Per bootstrap guide: one artifact -> 2-5 downstream assets

const primaryAssets = [
  {
    id: 'positioning-doc',
    title: 'Category Positioning Document: Artifact Governance',
    type: 'positioning',
    audience: 'all',
    chain: [
      { type: 'linkedin_post', title: 'Why PR Review is the New Compliance', audience: 'DevOps/Platform leads', length: '200-300 words', persona: 'builder' },
      { type: 'email_sequence', title: 'Artifact Governance cold outreach sequence (5-email)', audience: 'AppSec/Compliance leads', length: '80-140 words each', persona: 'buyer' },
      { type: 'landing_page_copy', title: 'GuardSpine.ai hero section rewrite', audience: 'all personas', length: '150 words', persona: 'all' },
      { type: 'twitter_thread', title: '10-tweet thread: Why DevOps missed the governance gap', audience: 'technical founders', length: '10 tweets', persona: 'builder' },
      { type: 'sales_one_pager', title: 'GuardSpine one-pager for enterprise prospects', audience: 'CTO/VP Eng', length: '1 page', persona: 'buyer' }
    ]
  },
  {
    id: 'codeguard-blog',
    title: 'Blog: Why PR Review is the New Compliance',
    type: 'blog_post',
    audience: 'DevOps/Platform leads',
    chain: [
      { type: 'linkedin_post', title: 'LinkedIn version (3 key points)', audience: 'DevOps', length: '200 words', persona: 'builder' },
      { type: 'dev_to_post', title: 'Dev.to cross-post', audience: 'developers', length: 'same', persona: 'builder' },
      { type: 'email_newsletter', title: 'Newsletter version with CTA', audience: 'subscribers', length: '300 words', persona: 'all' },
      { type: 'lead_magnet', title: 'The Artifact Governance Checklist (PDF gate)', audience: 'all', length: '1 page checklist', persona: 'all' }
    ]
  },
  {
    id: 'sanjay-demo',
    title: 'CodeGuard 10-Minute Demo Flow',
    type: 'demo_script',
    audience: 'prospect: Sanjay Nagaraj',
    chain: [
      { type: 'call_script', title: 'Discovery call opening (2 min)', audience: 'all enterprise prospects', length: '2 min script', persona: 'buyer' },
      { type: 'objection_guide', title: 'Top 5 demo objections + rebuttals', audience: 'David', length: '1 page', persona: 'all' },
      { type: 'pilot_proposal', title: 'GuardSpine pilot proposal template', audience: 'enterprise CTO', length: '2 pages', persona: 'buyer' },
      { type: 'follow_up_sequence', title: 'Post-demo 3-email follow-up', audience: 'demo attendees', length: '80 words each', persona: 'buyer' }
    ]
  }
];

// Queue all derivative assets as Paperclip issues
const tasks = [];
for (const asset of primaryAssets) {
  for (const derivative of asset.chain) {
    tasks.push({
      primary_id: asset.id,
      primary_title: asset.title,
      derivative_type: derivative.type,
      title: `[CHAIN] ${derivative.title}`,
      description: `Asset chain derivative from: ${asset.title}\n\nType: ${derivative.type}\nAudience: ${derivative.audience}\nPersona: ${derivative.persona}\nLength: ${derivative.length}\n\nParent asset: ${asset.id}\nChain rule: Bootstrap Guide §XIV.A`,
      priority: 'medium',
      lane: 'marketing'
    });
  }
}

return tasks.map(t => ({ json: t }));

const allItems = $input.all();
const created = allItems.filter(i => !i.json.error && i.json.id);
const failed = allItems.filter(i => i.json.error || !i.json.id);

return [{
  json: {
    total_derivatives: allItems.length,
    created: created.length,
    failed: failed.length,
    summary: `Asset chain generated: ${created.length}/${allItems.length} derivative tasks queued`,
    timestamp: new Date().toISOString()
  }
}];

